import { extractText, getDocumentProxy } from "npm:unpdf@2.2.2";
import { strFromU8, unzipSync } from "npm:fflate@0.8.3";
async function resumeText(bytes, ext) {
  if (ext === "pdf") {
    const pdf = await getDocumentProxy(bytes);
    const { text } = await extractText(pdf, { mergePages: true });
    return text;
  }
  if (ext === "docx") {
    const files = unzipSync(bytes, { filter: (f) => f.name === "word/document.xml" });
    const xml = strFromU8(files["word/document.xml"] ?? new Uint8Array());
    return xml.replace(/<w:tab\/>/g, "	").replace(/<\/w:p>|<w:br\/>/g, "\n").replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/\n{3,}/g, "\n\n").trim();
  }
  return new TextDecoder().decode(bytes);
}

